import { db } from '../database/index.ts';
import { suppliers, purchases } from '../database/schema.ts';
import { eq, like, or, desc } from 'drizzle-orm';

export class SupplierRepository {
  static async findAll(search?: string) {
    if (search) {
      const term = `%${search}%`;
      return await db.select().from(suppliers).where(
        or(
          like(suppliers.name, term),
          like(suppliers.phone, term)
        )
      );
    }
    return await db.select().from(suppliers);
  }

  static async findById(id: string) {
    const result = await db.select().from(suppliers).where(eq(suppliers.id, id));
    return result[0] || null;
  }

  static async upsert(supplierData: any) {
    const existing = await this.findById(supplierData.id);
    if (existing) {
      await db.update(suppliers).set(supplierData).where(eq(suppliers.id, supplierData.id));
    } else {
      await db.insert(suppliers).values(supplierData);
    }
    return supplierData;
  }

  static async updateBalance(id: string, newBalance: number) {
    await db.update(suppliers).set({ balance: newBalance.toString() }).where(eq(suppliers.id, id));
    return await this.findById(id);
  }

  static async adjustBalance(id: string, deltaAmount: number) {
    const supplier = await this.findById(id);
    if (!supplier) throw new Error('المورد غير موجود');
    const current = parseFloat(supplier.balance || '0');
    const updated = current + deltaAmount;
    await this.updateBalance(id, updated);
    return updated;
  }

  static async getSupplierPurchases(supplierId: string) {
    return await db.select().from(purchases).where(eq(purchases.supplierId, supplierId)).orderBy(desc(purchases.createdAt));
  }

  static async getSupplierLedger(supplierId: string, startDate?: string, endDate?: string) {
    const supplier = await this.findById(supplierId);
    if (!supplier) throw new Error('المورد غير موجود');

    const purList = await this.getSupplierPurchases(supplierId);
    const openingBalance = parseFloat((supplier as any).openingBalance || supplier.balance || '0');
    let runningBalance = openingBalance;

    const rawLines: any[] = [];

    purList.forEach(pur => {
      const gTotal = parseFloat(pur.grandTotal || '0');
      rawLines.push({
        id: `pur-${pur.id}`,
        date: pur.date ? pur.date.split('T')[0] : new Date().toISOString().split('T')[0],
        type: 'purchase_invoice',
        typeLabel: 'فاتورة مشتريات',
        reference: pur.supplierInvoiceNumber || pur.purchaseNumber,
        credit: gTotal, // Purchase invoice increases payable to supplier (Credit)
        debit: 0,
        notes: `فاتورة مشتريات رقم ${pur.purchaseNumber}`
      });
    });

    rawLines.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const transactions = rawLines.map(line => {
      runningBalance += (line.credit - line.debit);
      return {
        ...line,
        runningBalance: parseFloat(runningBalance.toFixed(2))
      };
    });

    return {
      supplier: {
        ...supplier,
        balance: parseFloat(supplier.balance || '0')
      },
      openingBalance,
      closingBalance: runningBalance,
      transactions,
      ledgerLines: transactions
    };
  }

  static async getSupplierStatement(supplierId: string, startDate?: string, endDate?: string) {
    return await this.getSupplierLedger(supplierId, startDate, endDate);
  }

  static async delete(id: string) {
    await db.delete(suppliers).where(eq(suppliers.id, id));
    return { success: true };
  }
}
